:root {
    --primary-color: #fce4ec; /* Soft pink */
    --accent-color: #e91e63; /* Deep pink/magenta */
    --text-dark: #333;
    --text-light: #fff;
    --glass-bg: rgba(255, 255, 255, 0.2);
    --glass-border: rgba(255, 255, 255, 0.4);
    --glass-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.37);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    background: linear-gradient(135deg, #fce4ec 0%, #f8bbd0 100%);
    color: var(--text-dark);
    font-family: 'Inter', sans-serif;
    min-height: 100vh;
    overflow-x: hidden;
}

.greeting-font {
    font-family: 'Great Vibes', cursive;
}

.body-font {
    font-family: 'Outfit', sans-serif;
}

.hidden {
    display: none !important;
    opacity: 0;
}

/* OVERLAY (Splash Screen) */
.overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 9999;
    color: var(--text-light);
    transition: opacity 1s ease-out;
}

.overlay-content {
    text-align: center;
}

.overlay-content h1 {
    font-size: 4rem;
    margin-bottom: 1rem;
    color: var(--primary-color);
    text-shadow: 0 0 20px rgba(233, 30, 99, 0.5);
}

.overlay-content p {
    font-size: 1.2rem;
    margin-bottom: 2rem;
    opacity: 0.8;
}

/* GLOW BUTTON */
.glow-on-hover {
    width: 220px;
    height: 60px;
    border: none;
    outline: none;
    color: #fff;
    background: var(--accent-color);
    cursor: pointer;
    position: relative;
    z-index: 0;
    border-radius: 30px;
    font-size: 1.2rem;
    font-family: 'Outfit', sans-serif;
    font-weight: 600;
    transition: transform 0.2s ease;
}

.glow-on-hover:hover {
    transform: scale(1.05);
}

.glow-on-hover:before {
    content: '';
    background: linear-gradient(45deg, #ff0000, #ff7300, #fffb00, #48ff00, #00ffd5, #002bff, #7a00ff, #ff00c8, #ff0000);
    position: absolute;
    top: -2px;
    left:-2px;
    background-size: 400%;
    z-index: -1;
    filter: blur(5px);
    width: calc(100% + 4px);
    height: calc(100% + 4px);
    animation: glowing 20s linear infinite;
    opacity: 0;
    transition: opacity .3s ease-in-out;
    border-radius: 30px;
}

.glow-on-hover:hover:before {
    opacity: 1;
}

.glow-on-hover:after {
    z-index: -1;
    content: '';
    position: absolute;
    width: 100%;
    height: 100%;
    background: var(--accent-color);
    left: 0;
    top: 0;
    border-radius: 30px;
}

@keyframes glowing {
    0% { background-position: 0 0; }
    50% { background-position: 400% 0; }
    100% { background-position: 0 0; }
}

/* MAIN CONTENT */
main {
    transition: opacity 1.5s ease-in;
}

.hero {
    min-height: 80vh;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 2rem;
    position: relative;
}

.glass-panel {
    background: var(--glass-bg);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--glass-border);
    box-shadow: var(--glass-shadow);
    border-radius: 24px;
    padding: 4rem 3rem;
    max-width: 800px;
    text-align: center;
    animation: slideUp 1.5s ease-out;
}

@keyframes slideUp {
    from {
        transform: translateY(50px);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

.title {
    font-size: 5rem;
    color: var(--accent-color);
    margin-bottom: 0.5rem;
    line-height: 1.2;
}

.subtitle {
    font-size: 4rem;
    color: var(--text-dark);
    margin-bottom: 2rem;
}

.hero-text {
    font-size: 1.3rem;
    line-height: 1.6;
    color: #444;
}

/* GALLERY SECTION */
.gallery-section {
    padding: 4rem 2rem;
    text-align: center;
}

.section-title {
    font-size: 4rem;
    color: var(--accent-color);
    margin-bottom: 3rem;
}

.masonry-grid {
    column-count: 3;
    column-gap: 20px;
    max-width: 1200px;
    margin: 0 auto;
}

.grid-item {
    break-inside: avoid;
    margin-bottom: 20px;
    position: relative;
    overflow: hidden;
    border-radius: 16px;
    box-shadow: 0 10px 20px rgba(0,0,0,0.1);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.grid-item img {
    width: 100%;
    height: auto;
    display: block;
    border-radius: 16px;
    transition: transform 0.5s ease;
}

.grid-item:hover {
    transform: translateY(-5px);
    box-shadow: 0 15px 30px rgba(0,0,0,0.2);
}

.grid-item:hover img {
    transform: scale(1.05);
}

@media (max-width: 900px) {
    .masonry-grid {
        column-count: 2;
    }
    .title {
        font-size: 4rem;
    }
    .subtitle {
        font-size: 3rem;
    }
}

@media (max-width: 600px) {
    .masonry-grid {
        column-count: 1;
    }
    .title {
        font-size: 3rem;
    }
    .subtitle {
        font-size: 2.5rem;
    }
    .hero-text {
        font-size: 1.1rem;
    }
    .glass-panel {
        padding: 3rem 1.5rem;
    }
}

/* FOOTER */
.footer {
    text-align: center;
    padding: 2rem;
    background: rgba(255, 255, 255, 0.5);
    color: var(--accent-color);
    font-weight: bold;
}

/* FIREFLIES ANIMATION */
.fireflies {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: -1;
}

.firefly {
    position: absolute;
    width: 6px;
    height: 6px;
    background: var(--accent-color);
    border-radius: 50%;
    box-shadow: 0 0 10px 2px var(--accent-color);
    animation: drift 15s infinite ease-in-out;
    opacity: 0.6;
}

@keyframes drift {
    0% {
        transform: translate(0, 0) scale(1);
        opacity: 0.6;
    }
    50% {
        transform: translate(calc(10vw - 5vw), calc(-20vh)) scale(1.5);
        opacity: 0.2;
    }
    100% {
        transform: translate(calc(20vw - 10vw), calc(-40vh)) scale(1);
        opacity: 0.6;
    }
}

// YouTube Iframe API setup
let player;
function onYouTubeIframeAPIReady() {
    player = new YT.Player('player', {
        height: '0',
        width: '0',
        videoId: 'xpfMlUlEBPU', // Phoolon Ka Taaron Ka
        playerVars: {
            'playsinline': 1,
            'controls': 0,
            'showinfo': 0,
            'rel': 0,
            'loop': 1,
            'playlist': 'xpfMlUlEBPU'
        },
        events: {
            'onReady': onPlayerReady
        }
    });
}

function onPlayerReady(event) {
    // Player is ready, enable the button
    const startBtn = document.getElementById('start-btn');
    startBtn.innerText = "Open Gift 🎁";
    startBtn.disabled = false;
}

// Ensure button says 'Loading...' until API is ready
document.addEventListener('DOMContentLoaded', () => {
    const startBtn = document.getElementById('start-btn');
    if (!player) {
        startBtn.innerText = "Loading surprise...";
    }

    startBtn.addEventListener('click', () => {
        // Try to play audio
        if (player && typeof player.playVideo === 'function') {
            player.playVideo();
        }

        // Fade out overlay
        const overlay = document.getElementById('intro-overlay');
        overlay.style.opacity = '0';

        setTimeout(() => {
            overlay.style.display = 'none';
            // Show main content
            const mainContent = document.getElementById('main-content');
            mainContent.classList.remove('hidden');
        }, 1000);
    });

    // Create Fireflies
    const firefliesContainer = document.getElementById('fireflies-container');
    const numFireflies = 30;
    for (let i = 0; i < numFireflies; i++) {
        let firefly = document.createElement('div');
        firefly.classList.add('firefly');

        // Random positioning and animation duration
        let top = Math.random() * 100;
        let left = Math.random() * 100;
        let animDuration = 10 + Math.random() * 15;
        let delay = Math.random() * 5;

        firefly.style.top = `${top}vh`;
        firefly.style.left = `${left}vw`;
        firefly.style.animationDuration = `${animDuration}s`;
        firefly.style.animationDelay = `${delay}s`;

        firefliesContainer.appendChild(firefly);
    }

    // Try to load images dynamically (1 to 10)
    loadImages();
});

async function loadImages() {
    const gallery = document.getElementById('photo-gallery');
    const maxImages = 10;
    const extensions = ['jpg', 'jpeg', 'png'];

    for (let i = 1; i <= maxImages; i++) {
        for (let ext of extensions) {
            let imgUrl = `assets/images/${i}.${ext}`;
            try {
                // Check if image exists
                let response = await fetch(imgUrl, { method: 'HEAD' });
                if (response.ok) {
                    let div = document.createElement('div');
                    div.classList.add('grid-item');
                    let img = document.createElement('img');
                    img.src = imgUrl;
                    img.alt = `Memory ${i}`;
                    img.loading = 'lazy';
                    div.appendChild(img);
                    gallery.appendChild(div);
                    break; // If found, go to next index
                }
            } catch (error) {
                // Ignore fetch errors
            }
        }
    }
}

