:root {
    --bg-color: #F9F9F7;
    --text-primary: #1A1A1A;
    --text-secondary: #5A5A58;
    --accent-color: #D34C37; /* A chic muted terracotta/red for accents */

    --font-heading: 'Outfit', sans-serif;
    --font-body: 'Inter', sans-serif;

    --spacing-sm: 1rem;
    --spacing-md: 2rem;
    --spacing-lg: 5rem;
    --spacing-xl: 10rem;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-body);
    background-color: var(--bg-color);
    color: var(--text-primary);
    line-height: 1.6;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}

.hidden {
    display: none !important;
}

/* --- OVERLAY LAUNCH SCREEN --- */
.overlay {
    position: fixed;
    top: 0; left: 0; width: 100vw; height: 100vh;
    background-color: var(--text-primary);
    color: #FFF;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 9999;
    transition: opacity 1s cubic-bezier(0.77, 0, 0.175, 1);
}

.overlay-content {
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1.5rem;
}

.overlay-title {
    font-family: var(--font-heading);
    font-weight: 300;
    font-size: 2.5rem;
    letter-spacing: 0.05em;
}

.overlay-subtitle {
    font-size: 1rem;
    color: #A0A0A0;
    margin-bottom: 2rem;
}

#start-btn {
    padding: 1rem 3rem;
    font-family: var(--font-heading);
    font-size: 1.1rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    background: transparent;
    color: #FFF;
    border: 1px solid rgba(255,255,255,0.3);
    border-radius: 50px;
    cursor: pointer;
    transition: all 0.4s ease;
}

#start-btn:not(:disabled):hover {
    background: #FFF;
    color: var(--text-primary);
    transform: translateY(-2px);
}

#start-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* --- HERO SECTION --- */
.hero {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: var(--spacing-lg) var(--spacing-md);
}

.hero-content {
    text-align: center;
    max-width: 800px;
}

.hero-title {
    font-family: var(--font-heading);
    font-weight: 300;
    font-size: clamp(2.5rem, 5vw, 4rem);
    text-transform: uppercase;
    letter-spacing: 0.2em;
    color: var(--text-secondary);
    margin-bottom: 1rem;
}

.hero-name {
    font-family: var(--font-heading);
    font-weight: 800;
    font-size: clamp(4rem, 10vw, 8rem);
    line-height: 1;
    letter-spacing: -0.02em;
    margin-bottom: 2rem;
}

.hero-divider {
    width: 60px;
    height: 3px;
    background-color: var(--accent-color);
    margin: 0 auto 2rem auto;
}

.hero-text {
    font-size: clamp(1.1rem, 2vw, 1.5rem);
    font-weight: 300;
    color: var(--text-secondary);
    max-width: 600px;
    margin: 0 auto;
}

/* --- EDITORIAL GALLERY --- */
.editorial-gallery {
    padding: 0 var(--spacing-md) var(--spacing-xl) var(--spacing-md);
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-xl);
}

.editorial-block {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
}

.editorial-block.alt-layout {
    flex-direction: row-reverse;
}

.image-wrapper {
    flex: 1;
    position: relative;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 20px 40px rgba(0,0,0,0.08);
}

.image-wrapper img {
    width: 100%;
    height: auto;
    display: block;
    object-fit: cover;
    transform: scale(1.05);
    transition: transform 1.5s cubic-bezier(0.165, 0.84, 0.44, 1);
}

.editorial-block:hover .image-wrapper img {
    transform: scale(1);
}

.text-wrapper {
    flex: 1;
    max-width: 450px;
    padding: var(--spacing-md);
}

.chapter-num {
    font-family: var(--font-heading);
    font-size: 1rem;
    font-weight: 600;
    color: var(--accent-color);
    letter-spacing: 0.1em;
    margin-bottom: 1rem;
    display: block;
}

.text-wrapper h3 {
    font-family: var(--font-heading);
    font-size: clamp(2rem, 4vw, 3rem);
    font-weight: 600;
    margin-bottom: 1.5rem;
    line-height: 1.1;
}

.text-wrapper p {
    font-size: 1.15rem;
    color: var(--text-secondary);
}

/* --- FINALE BLOCK --- */
.editorial-finale {
    text-align: center;
    margin-top: var(--spacing-lg);
}

.finale-image-wrapper {
    max-width: 800px;
    margin: 0 auto var(--spacing-lg) auto;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 30px 60px rgba(0,0,0,0.12);
}

.finale-image-wrapper img {
    width: 100%;
    height: auto;
    display: block;
}

.finale-text {
    max-width: 700px;
    margin: 0 auto;
}

.finale-text h2 {
    font-family: var(--font-heading);
    font-size: clamp(2.5rem, 5vw, 4rem);
    font-weight: 800;
    margin-bottom: 1rem;
}

.finale-text p {
    font-size: clamp(1.2rem, 3vw, 1.8rem);
    color: var(--text-secondary);
    font-weight: 300;
}

/* --- FOOTER --- */
.footer {
    text-align: center;
    padding: var(--spacing-lg) 0;
    font-size: 0.9rem;
    color: var(--text-secondary);
    border-top: 1px solid rgba(0,0,0,0.05);
}

/* --- SCROLL ANIMATIONS --- */
.reveal {
    opacity: 0;
    transform: translateY(40px);
    transition: all 1s cubic-bezier(0.165, 0.84, 0.44, 1);
}

.reveal.active {
    opacity: 1;
    transform: translateY(0);
}

/* --- RESPONSIVE --- */
@media (max-width: 900px) {
    .editorial-block, .editorial-block.alt-layout {
        flex-direction: column;
        gap: var(--spacing-md);
    }

    .text-wrapper {
        padding: 0;
        text-align: center;
    }
}

// YouTube Iframe API setup
let player;
function onYouTubeIframeAPIReady() {
    player = new YT.Player('player', {
        height: '0',
        width: '0',
        videoId: 'qFkNATtc3mc', // Ghungroo (War)
        playerVars: {
            'playsinline': 1,
            'controls': 0,
            'showinfo': 0,
            'rel': 0,
            'loop': 1,
            'playlist': 'qFkNATtc3mc' // Loop needs playlist to be same video
        },
        events: {
            'onReady': onPlayerReady
        }
    });
}

function onPlayerReady(event) {
    // Player is ready, enable the button
    const startBtn = document.getElementById('start-btn');
    startBtn.innerText = "Begin Experience";
    startBtn.disabled = false;
}

document.addEventListener('DOMContentLoaded', () => {
    const startBtn = document.getElementById('start-btn');
    if (!player) {
        startBtn.innerText = "Loading experience...";
    }

    startBtn.addEventListener('click', () => {
        // Try to play audio
        if (player && typeof player.playVideo === 'function') {
            player.playVideo();
        }

        // Fade out overlay
        const overlay = document.getElementById('intro-overlay');
        overlay.style.opacity = '0';

        setTimeout(() => {
            overlay.style.display = 'none';
            // Show main content
            const mainContent = document.getElementById('main-content');
            mainContent.classList.remove('hidden');

            // Trigger initial scroll reveals
            initScrollReveals();
        }, 1000);
    });
});

// Intersection Observer for scroll animations
function initScrollReveals() {
    const reveals = document.querySelectorAll('.reveal');

    const revealOptions = {
        threshold: 0.15,
        rootMargin: "0px 0px -50px 0px"
    };

    const revealOnScroll = new IntersectionObserver(function(entries, observer) {
        entries.forEach(entry => {
            if (!entry.isIntersecting) {
                return;
            } else {
                entry.target.classList.add('active');
                observer.unobserve(entry.target); // Only animate once
            }
        });
    }, revealOptions);

    reveals.forEach(reveal => {
        revealOnScroll.observe(reveal);
    });
}

