/* --- DYNAMIC GALLERY --- */
.dynamic-gallery {
    padding: 0 var(--spacing-md) var(--spacing-xl) var(--spacing-md);
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 8rem;
}

.layout-block {
    position: relative;
    width: 100%;
}

.image-box {
    position: relative;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 20px 40px rgba(0,0,0,0.1);
}

.image-box img {
    width: 100%;
    height: auto;
    display: block;
    object-fit: cover;
}

/* Z-Index utils */
.z-index-1 { z-index: 1; }
.z-index-2 { z-index: 2; }
.z-index-3 { z-index: 3; }

/* typography */
.pop-title {
    font-family: var(--font-heading);
    font-size: clamp(2.5rem, 4vw, 3.5rem);
    font-weight: 800;
    line-height: 1.1;
    margin-bottom: 1rem;
    color: var(--text-primary);
}

.chapter-num {
    font-family: var(--font-heading);
    font-size: 1.2rem;
    font-weight: 600;
    color: var(--accent-color);
    letter-spacing: 0.1em;
    margin-bottom: 0.5rem;
    display: block;
}

/* 1. Overlapping Block */
.block-overlap {
    display: flex;
    align-items: center;
    justify-content: flex-end;
}

.block-overlap .image-box {
    width: 70%;
    margin-left: auto;
}

.floating-card {
    position: absolute;
    left: 0;
    background: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    padding: 3rem;
    border-radius: 16px;
    box-shadow: 0 30px 60px rgba(0,0,0,0.1);
    max-width: 450px;
}

/* 2. Duo Grid */
.block-duo {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: start;
}

.duo-column {
    display: flex;
    flex-direction: column;
    gap: 2rem;
}

.offset-down {
    margin-top: 6rem;
}

.clean {
    padding: 1rem 0;
}

/* 3. Hero Scale (Solo Photo) */
.block-hero {
    display: flex;
    justify-content: center;
    margin-top: 4rem;
}

.giant-text {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-family: var(--font-heading);
    font-size: clamp(4rem, 15vw, 12rem);
    font-weight: 800;
    color: rgba(0,0,0,0.03);
    white-space: nowrap;
    pointer-events: none;
}

.portrait-tall {
    width: 60%;
    max-width: 500px;
}

.bottom-right {
    bottom: -3rem;
    left: auto;
    right: 5%;
}

/* 4. Finale (Circular Expansion) */
.block-finale {
    text-align: center;
    margin-top: 8rem;
}

.finale-mask {
    max-width: 800px;
    margin: 0 auto 3rem auto;
    clip-path: circle(70% at 50% 50%);
    transition: clip-path 1.5s cubic-bezier(0.165, 0.84, 0.44, 1);
}

.block-finale.active .finale-mask {
    clip-path: circle(100% at 50% 50%);
}

.finale-text h2 {
    font-family: var(--font-heading);
    font-size: clamp(3rem, 6vw, 5rem);
    font-weight: 800;
    margin-bottom: 1rem;
    text-transform: uppercase;
}

.finale-text p {
    font-size: clamp(1.2rem, 3vw, 1.8rem);
    color: var(--text-secondary);
    max-width: 700px;
    margin: 0 auto;
}

/* --- FOOTER --- */
.footer {
    text-align: center;
    padding: var(--spacing-lg) 0;
    font-size: 0.9rem;
    color: var(--text-secondary);
    border-top: 1px solid rgba(0,0,0,0.05);
}

/* --- ADVANCED ANIMATIONS (Reveals) --- */
.reveal, .reveal-up, .reveal-left, .reveal-right, .reveal-zoom {
    opacity: 0;
    transition: all 1.2s cubic-bezier(0.165, 0.84, 0.44, 1);
}

.reveal { transform: translateY(40px); }
.reveal-up { transform: translateY(80px); }
.reveal-left { transform: translateX(-60px); }
.reveal-right { transform: translateX(60px); }
.reveal-zoom { transform: scale(0.9); }

.reveal.active, .reveal-up.active, .reveal-left.active, .reveal-right.active, .reveal-zoom.active {
    opacity: 1;
    transform: translate(0) scale(1);
}

/* --- INTERACTIVE ANIMATIONS --- */
.tilt-hover {
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.tilt-hover:hover {
    transform: scale(1.02) rotate(-1deg);
}

.parallax img {
    transition: transform 0.5s ease-out;
}

.parallax:hover img {
    transform: translateY(-10px) scale(1.05);
}

/* --- RESPONSIVE --- */
@media (max-width: 900px) {
    .block-overlap .image-box {
        width: 100%;
    }
    .floating-card {
        position: relative;
        max-width: 100%;
        margin-top: -3rem;
        padding: 2rem;
    }
    .block-duo {
        grid-template-columns: 1fr;
        gap: 3rem;
    }
    .offset-down {
        margin-top: 0;
