/* --- EDITORIAL GALLERY --- */
.editorial-gallery {
    padding: 0 var(--spacing-md) var(--spacing-xl) var(--spacing-md);
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-xl);
}

.editorial-block {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
}

.editorial-block.alt-layout {
    flex-direction: row-reverse;
}

.image-wrapper {
    flex: 1;
    position: relative;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 20px 40px rgba(0,0,0,0.08);
}

.image-wrapper img {
    width: 100%;
    height: auto;
    display: block;
    object-fit: cover;
    transform: scale(1.05);
    transition: transform 1.5s cubic-bezier(0.165, 0.84, 0.44, 1);
}

.editorial-block:hover .image-wrapper img {
    transform: scale(1);
}

.text-wrapper {
    flex: 1;
    max-width: 450px;
    padding: var(--spacing-md);
}

.chapter-num {
    font-family: var(--font-heading);
    font-size: 1rem;
    font-weight: 600;
    color: var(--accent-color);
    letter-spacing: 0.1em;
    margin-bottom: 1rem;
    display: block;
}

.text-wrapper h3 {
    font-family: var(--font-heading);
    font-size: clamp(2rem, 4vw, 3rem);
    font-weight: 600;
    margin-bottom: 1.5rem;
    line-height: 1.1;
}

.text-wrapper p {
    font-size: 1.15rem;
    color: var(--text-secondary);
}

/* --- FINALE BLOCK --- */
.editorial-finale {
    text-align: center;
    margin-top: var(--spacing-lg);
}

.finale-image-wrapper {
    max-width: 800px;
    margin: 0 auto var(--spacing-lg) auto;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 30px 60px rgba(0,0,0,0.12);
}

.finale-image-wrapper img {
    width: 100%;
    height: auto;
    display: block;
}

.finale-text {
    max-width: 700px;
    margin: 0 auto;
}

.finale-text h2 {
    font-family: var(--font-heading);
    font-size: clamp(2.5rem, 5vw, 4rem);
    font-weight: 800;
    margin-bottom: 1rem;
}

.finale-text p {
    font-size: clamp(1.2rem, 3vw, 1.8rem);
    color: var(--text-secondary);
    font-weight: 300;
}

/* --- FOOTER --- */
.footer {
    text-align: center;
    padding: var(--spacing-lg) 0;
    font-size: 0.9rem;
    color: var(--text-secondary);
    border-top: 1px solid rgba(0,0,0,0.05);
}

/* --- SCROLL ANIMATIONS --- */
.reveal {
    opacity: 0;
    transform: translateY(40px);
    transition: all 1s cubic-bezier(0.165, 0.84, 0.44, 1);
}

.reveal.active {
    opacity: 1;
    transform: translateY(0);
}

/* --- RESPONSIVE --- */
@media (max-width: 900px) {
    .editorial-block, .editorial-block.alt-layout {
        flex-direction: column;
        gap: var(--spacing-md);
    }

    .text-wrapper {
        padding: 0;
        text-align: center;
    }
}

