args.ReplacementContent:
/* --- RESPONSIVE --- */
@media (max-width: 900px) {
    .block-overlap, .block-overlap-reverse {
        /* Reverse the DOM order so image sits on top of text card */
        flex-direction: column-reverse; 
    }

    .block-hero {
        flex-direction: column;
    }

    .block-overlap .image-box, .block-overlap-reverse .image-box, .block-hero .image-box {
        width: 100%;
        margin: 0;
    }

    .layout-block {
        margin-bottom: 6rem;
    }

    .floating-card, .floating-card.right-side, .floating-card.bottom-right {
        position: relative;
        width: 92%;
        max-width: none;
        margin: -15% auto 0; /* Pulls text card up over the image beautifully */
        padding: 2rem 1.5rem;
        left: auto;
        right: auto;
        bottom: auto;
        z-index: 10;
        border-radius: 20px;
    }

    .block-duo {
        grid-template-columns: 1fr;
        gap: 3rem;
    }

    .offset-down {
        margin-top: 0;
    }

    .portrait-tall {
        width: 100%;
    }

