// --- MAGIC DUST INTERACTIVE BACKGROUND ---
const canvas = document.getElementById('magic-dust');
const ctx = canvas.getContext('2d');

let particles = [];
const colors = ['#FFB6C1', '#FFE4B5', '#E6E6FA', '#FFFFFF', '#FFDAB9'];

function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

class Particle {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.size = Math.random() * 3 + 1;
        this.speedX = Math.random() * 2 - 1;
        this.speedY = Math.random() * -2 - 0.5; // Float upwards
        this.color = colors[Math.floor(Math.random() * colors.length)];
        this.opacity = 1;
        this.decay = Math.random() * 0.02 + 0.01;
    }
    update() {
        this.x += this.speedX;
        this.y += this.speedY;
        this.opacity -= this.decay;
        this.size -= 0.05;
    }
    draw() {
        ctx.save();
        ctx.globalAlpha = this.opacity;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.shadowBlur = 10;
        ctx.shadowColor = this.color;
        ctx.restore();
    }
}

function handleParticles() {
    for (let i = 0; i < particles.length; i++) {
        particles[i].update();
        particles[i].draw();
        if (particles[i].opacity <= 0 || particles[i].size <= 0) {
            particles.splice(i, 1);
            i--;
        }
    }
}

function spawnParticles(e) {
    const x = e.clientX || (e.touches && e.touches[0].clientX);
    const y = e.clientY || (e.touches && e.touches[0].clientY);

    // Spawn 2-3 particles per move
    for(let i=0; i<3; i++) {
        particles.push(new Particle(x, y));
    }
}

window.addEventListener('mousemove', spawnParticles);
window.addEventListener('touchmove', spawnParticles);

function animateDust() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    handleParticles();
    requestAnimationFrame(animateDust);
}
animateDust();

