class Particle {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.size = Math.random() * 3 + 2; // Start larger so decay is safe
        this.speedX = Math.random() * 2 - 1;
        this.speedY = Math.random() * -2 - 0.5;
        this.color = colors[Math.floor(Math.random() * colors.length)];
        this.opacity = 1;
        this.decay = Math.random() * 0.02 + 0.01;
        this.alive = true;
    }
    update() {
        this.x += this.speedX;
        this.y += this.speedY;
        this.opacity -= this.decay;
        this.size -= 0.05;
        // Mark dead if too small or invisible
        if (this.size <= 0.1 || this.opacity <= 0) {
            this.alive = false;
        }
    }
    draw() {
        // NEVER call arc with negative or zero radius
        const safeSize = Math.max(0.1, this.size);
        ctx.save();
        ctx.globalAlpha = Math.max(0, Math.min(1, this.opacity));
        ctx.beginPath();
        ctx.arc(this.x, this.y, safeSize, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.shadowBlur = 6;
        ctx.shadowColor = this.color;
        ctx.restore();
    }
}

