}

/* --- DYNAMIC GALLERY --- */
.dynamic-gallery {
    padding: 10rem 5%;
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 8rem;
}

.layout-block {
    position: relative;
    width: 100%;
}

.image-box {
    position: relative;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 20px 40px rgba(0,0,0,0.1);
    border: 4px solid rgba(255, 255, 255, 0.85); /* Prominent white border */
    box-sizing: border-box;
    width: 100%;
    max-height: 80vh;
}

.image-box img {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    transition: transform 0.6s cubic-bezier(0.165, 0.84, 0.44, 1);
}

/* Z-Index utils */
.z-index-1 { z-index: 1; }
.z-index-2 { z-index: 2; }
.z-index-3 { z-index: 3; }

/* typography */
.pop-title {
    font-family: var(--font-heading);
    font-size: clamp(2.5rem, 4vw, 3.5rem);
    font-weight: 800;
    line-height: 1.1;
    margin-bottom: 1rem;
    color: var(--text-primary);
}

.chapter-num {
    font-family: var(--font-heading);
    font-size: 1.2rem;
    font-weight: 600;
    color: var(--accent-color);
    letter-spacing: 0.1em;
    margin-bottom: 0.5rem;
    display: block;
}

/* 1. Overlapping Block */
.block-overlap {
    display: flex;
    align-items: center;
    justify-content: flex-end;
}

.block-overlap .image-box {
    width: 70%;
    margin-left: auto;
}

.floating-card {
    position: absolute;
    left: 0;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    padding: 3rem;
    border-radius: 16px;
    border: 1px solid rgba(255, 255, 255, 0.5);
    box-shadow: 0 30px 60px rgba(230, 81, 0, 0.08);
    max-width: 450px;
    box-sizing: border-box;
}

/* Overlap Reverse */
.block-overlap-reverse {
    display: flex;
    align-items: center;
    justify-content: flex-start;
}

.block-overlap-reverse .image-box {
    margin-left: 0;
    margin-right: auto;
}

.floating-card.right-side {
    left: auto;
    right: 0;
}


.image-duo-container {
    display: flex;
    gap: 1.5rem;
    width: 70%;
    margin-left: auto;
}
.block-overlap-reverse .image-duo-container {
    margin-left: 0;
    margin-right: auto;
}
.image-duo-container .image-box {
    width: 100%;
    margin: 0 !important;
}

/* 2. Duo Grid */
.block-duo {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: start;
}

.duo-column {
    display: flex;
    flex-direction: column;
    gap: 2rem;
}

.offset-down {
    margin-top: 6rem;
}

.clean {
    padding: 1rem 0;
}

/* 3. Hero Scale (Solo Photo) */
.block-hero {
    display: flex;
    justify-content: center;
    margin-top: 4rem;
}

.giant-text {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-family: var(--font-heading);
    font-size: clamp(4rem, 15vw, 12rem);
    font-weight: 800;
    color: rgba(230, 81, 0, 0.04);
    -webkit-text-stroke: 1px rgba(230, 81, 0, 0.08);
    white-space: nowrap;
    pointer-events: none;
}

.portrait-tall {
    width: 60%;
    max-width: 500px;
}

.bottom-right {
    bottom: -3rem;
    left: auto;
    right: 5%;
}

/* 4. Finale (Circular Expansion) */
.block-finale {
    text-align: center;
    margin-top: 8rem;
}

.finale-mask {
    max-width: 800px;
    margin: 0 auto 3rem auto;
    clip-path: circle(70% at 50% 50%);
    transition: clip-path 1.5s cubic-bezier(0.165, 0.84, 0.44, 1);
}

.block-finale.active .finale-mask {
    clip-path: circle(100% at 50% 50%);
}

.finale-text h2 {
    font-family: var(--font-heading);
    font-size: clamp(3rem, 6vw, 5rem);
    font-weight: 800;
    margin-bottom: 1rem;
    text-transform: uppercase;
}

.finale-text p {
    font-size: clamp(1.2rem, 3vw, 1.8rem);
    color: var(--text-secondary);
    max-width: 700px;
    margin: 0 auto;
}

/* --- FOOTER --- */
.footer {
    text-align: center;
    padding: var(--spacing-lg) 0;
    font-size: 0.9rem;
    color: var(--text-secondary);
    border-top: 1px solid rgba(0,0,0,0.05);
}

/* --- ADVANCED ANIMATIONS (Reveals) --- */
.reveal, .reveal-up, .reveal-left, .reveal-right, .reveal-zoom {
    opacity: 0;
    transition: all 1.2s cubic-bezier(0.165, 0.84, 0.44, 1);
}

.reveal { transform: translateY(60px) scale(0.95) rotate(2deg); }
.reveal-up { transform: translateY(100px) scale(0.95) rotate(-3deg); }
.reveal-left { transform: translateX(-80px) scale(0.95) rotate(3deg); }
.reveal-right { transform: translateX(80px) scale(0.95) rotate(-3deg); }
.reveal-zoom { transform: scale(0.8) rotate(4deg); }

.reveal.active, .reveal-up.active, .reveal-left.active, .reveal-right.active, .reveal-zoom.active {
    opacity: 1;
    transform: translate(0) scale(1) rotate(0deg);
}

/* --- INTERACTIVE ANIMATIONS --- */
.tilt-hover {
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.tilt-hover:hover {
    transform: scale(1.02) rotate(-1deg);
}

.parallax img {
    transition: transform 0.5s ease-out;
}

.parallax:hover img {
    transform: translateY(-10px) scale(1.05);
}

/* --- RESPONSIVE --- */
@media (max-width: 900px) {
    #main-content {
        width: 100%;
    }

        .dynamic-gallery {
        padding: 0 1.5rem 5rem 1.5rem !important; /* Force padding on mobile */
        gap: 8rem;
    }

        .block-overlap, .block-overlap-reverse {
        /* Reverse the DOM order so image sits on top of text card */
        flex-direction: column; 
        align-items: center; /* Ensure centered */
        gap: 2rem;
    }

    .block-hero {
        flex-direction: column;
        gap: 2rem;
    }


    .image-duo-container {
        width: 100%;
        flex-direction: column;
    }

    .block-overlap .image-box, .block-overlap-reverse .image-box, .block-hero .image-box {
        width: 100%;
        margin: 0;
    }



    .floating-card, .floating-card.right-side, .floating-card.bottom-right {
        position: relative;
        width: 100%;
        max-width: none;
        margin: 0;
        padding: 1.5rem;
