import re

with open('/Users/pratik.giramkar/rakhi/src/app.css', 'r') as f:
    content = f.read()

# 1. Update image-box and floating-card for world-class desktop
new_desktop_layout = """/* 1. Overlapping Block */
.block-overlap {
    display: flex;
    align-items: center;
    justify-content: flex-end;
}

.block-overlap .image-box {
    width: 60%;
    margin-left: auto;
    aspect-ratio: 4/5; /* Premium portrait ratio */
}

/* Overlap Reverse */
.block-overlap-reverse {
    display: flex;
    align-items: center;
    justify-content: flex-start;
}

.block-overlap-reverse .image-box {
    width: 60%;
    margin-right: auto;
    aspect-ratio: 4/5; /* Premium portrait ratio */
}

.floating-card {
    position: absolute;
    top: 50%;
    transform: translateY(-50%); /* Perfectly center vertically over the image */
    left: 0;
    background: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    padding: 3.5rem;
    border-radius: 20px;
    border: 1px solid rgba(255, 255, 255, 0.5);
    box-shadow: 0 30px 60px rgba(0, 0, 0, 0.1);
    max-width: 450px;
    width: 90%;
    box-sizing: border-box;
    z-index: 10;
}

.floating-card.right-side {
    left: auto;
    right: 0;
}

.image-duo-container {
    display: flex;
    gap: 2rem;
    width: 75%;
    margin-left: auto;
}
.block-overlap-reverse .image-duo-container {
    margin-left: 0;
    margin-right: auto;
}
.image-duo-container .image-box {
    width: 100%;
    margin: 0 !important;
    aspect-ratio: 4/5;
}"""

content = re.sub(r'/\* 1\. Overlapping Block \*/.*?(?=/\* 2\. Duo Grid \*/)', new_desktop_layout + '\n\n', content, flags=re.DOTALL)

# 2. Update mobile media query to remove the absolute positioning correctly
# Because we added top: 50% and transform to floating-card, we MUST reset it in mobile!
mobile_reset = """    .floating-card, .floating-card.right-side, .floating-card.bottom-right {
        position: relative;
        top: auto;
        transform: none;
        width: 100%;
        max-width: none;
        margin: 0;
        padding: 2rem;
        left: auto;
        right: auto;
        bottom: auto;
        border-radius: 16px;
        background: rgba(255, 255, 255, 0.4);
        border: none;
        box-shadow: none;
    }"""
content = re.sub(r'\s*\.floating-card, \.floating-card\.right-side, \.floating-card\.bottom-right\s*\{[^}]+\}', '\n' + mobile_reset, content)

# 3. Add object-position to .image-box img for better cropping
content = content.replace('object-fit: cover;', 'object-fit: cover;\n    object-position: center 20%;')

with open('/Users/pratik.giramkar/rakhi/src/app.css', 'w') as f:
    f.write(content)

print("Applied world-class desktop layout")
EOF
